        >();
bool doubleEqual(ffi.Pointer<ffi.Void> v1, ffi.Pointer<ffi.Void> v2) {
  return (_gDoubleEqual(v1, v2)) != 0;
}

/// Converts a pointer to a #gdouble to a hash value.
