/// but use the C_() macro for translations with context.
final _gDpgettext =
    glibLookup<
          ffi.NativeFunction<
            ffi.Pointer<Utf8> Function(
              ffi.Pointer<Utf8>,
              ffi.Pointer<Utf8>,
              ffi.Size,
            )
          >
        >('g_dpgettext')
        .asFunction<
          ffi.Pointer<Utf8> Function(ffi.Pointer<Utf8>, ffi.Pointer<Utf8>, int)
        >();
