  return withNativeString(domain, (nativeDomain) {
    return withNativeString(msgctxtid, (nativeMsgctxtid) {
      return stringFromNative(
        (_gDpgettext(
          nativeDomain.cast<Utf8>(),
          nativeMsgctxtid.cast<Utf8>(),
          msgidoffset,
        )).cast(),
        free: false,
      )!;
    });
  });
}
